const raw = $input.first().json;
const item = raw && raw.body ? raw.body : raw;
const startedAt = new Date().toISOString();

if (!item.execution_id) throw new Error('Missing execution_id in payload');
if (!item.callback || !item.callback.url || !item.callback.secret) {
  throw new Error('Missing callback.url or callback.secret in payload');
}

const config = item.config || {};
const channel = (config.channel || '#general').toString();
const maxRisks = typeof config.max_risks === 'number' ? config.max_risks : 3;
const maxActions = typeof config.max_action_items === 'number' ? config.max_action_items : 4;
const simulateFailure = config.simulate_failure === true;

const providedItems = item.input && Array.isArray(item.input.items) ? item.input.items : [];
const messages = providedItems.length > 0 ? providedItems : [
  { user: 'alex',  text: 'Customer demo went well — they asked about SSO and audit logs.' },
  { user: 'mira',  text: 'API timeout spiked again this morning around 9am, looking into it.' },
  { user: 'kai',   text: 'Reminder: client review deadline is Friday — slides are 70% done.' },
  { user: 'mira',  text: 'Pushed a hotfix for the timeout, monitoring throughput now.' },
  { user: 'alex',  text: 'Two new prospects from the webinar, scoring them tomorrow.' },
  { user: 'sam',   text: 'Roadmap doc updated — please review by EOD Wednesday.' },
  { user: 'kai',   text: 'Need design review for the onboarding flow before Friday.' },
  { user: 'mira',  text: 'Latency back to baseline. Will write up post-mortem tomorrow.' },
  { user: 'alex',  text: 'Pricing experiment is converging — 3% lift on annual plans.' },
  { user: 'sam',   text: 'Heads up: vendor invoice deadline is end of week, finance asked us to confirm.' },
  { user: 'mira',  text: 'Considering moving the cron job to a separate worker — main process is noisy.' },
  { user: 'kai',   text: 'Customer success ticket about export-to-CSV failing on large datasets.' },
  { user: 'alex',  text: 'Marketing wants the case study live before the conference.' },
  { user: 'sam',   text: 'New hire onboarding starts Monday — calendar invites going out today.' },
  { user: 'mira',  text: 'Dependency security alert (low) on a transitive package — non-blocking.' },
  { user: 'kai',   text: 'Design review feedback: tighten the empty state copy on agents page.' },
  { user: 'alex',  text: 'Closed-won update: $24k ARR signed this morning.' },
  { user: 'sam',   text: 'Need someone to cover oncall Saturday — any takers?' },
  { user: 'mira',  text: 'Cron worker spike repro\'d locally — will ship a fix tomorrow.' },
  { user: 'kai',   text: 'Client review slides ready for dry-run at 4pm.' }
];

const buildCallback = (status, result, error, metrics) => {
  const finishedAt = new Date().toISOString();
  return {
    callbackUrl: item.callback.url,
    callbackSecret: item.callback.secret,
    callbackBody: {
      execution_id: item.execution_id,
      agent_instance_id: item.agent_instance_id,
      template_id: item.template_id,
      status,
      n8n_execution_id: $execution.id,
      started_at: startedAt,
      finished_at: finishedAt,
      metrics,
      result,
      error
    },
    httpResponse: { received: true, execution_id: item.execution_id, status }
  };
};

if (simulateFailure) {
  return [{
    json: buildCallback(
      'failed',
      null,
      { code: 'MOCK_PROVIDER_TIMEOUT', message: 'Simulated provider timeout for demo', retryable: true },
      { input_count: messages.length, output_count: 0, error_count: messages.length, tokens_input: 0, tokens_output: 0, estimated_cost_usd: 0 }
    )
  }];
}

const RISK_KEYWORDS = ['timeout', 'spike', 'failing', 'failed', 'security alert', 'deadline', 'oncall', 'invoice deadline', 'noisy'];
const THEME_KEYWORDS = {
  reliability: ['timeout', 'spike', 'latency', 'cron', 'worker', 'monitor', 'baseline'],
  delivery: ['deadline', 'review', 'slides', 'design review', 'roadmap'],
  customer: ['customer', 'prospect', 'pricing', 'webinar', 'closed-won', 'demo', 'case study'],
  ops: ['invoice', 'oncall', 'onboarding', 'security alert', 'vendor']
};

const lc = (s) => (s || '').toLowerCase();

const risks = [];
for (const m of messages) {
  const text = lc(m.text);
  for (const kw of RISK_KEYWORDS) {
    if (text.includes(kw)) {
      const sentence = (m.text || '').trim();
      if (sentence && !risks.some((r) => r.toLowerCase() === sentence.toLowerCase())) risks.push(sentence);
      break;
    }
  }
  if (risks.length >= maxRisks) break;
}

const themeHits = {};
for (const m of messages) {
  const text = lc(m.text);
  for (const [theme, kws] of Object.entries(THEME_KEYWORDS)) {
    if (kws.some((kw) => text.includes(kw))) {
      themeHits[theme] = (themeHits[theme] || 0) + 1;
    }
  }
}
const themesRanked = Object.entries(themeHits).sort((a, b) => b[1] - a[1]).map(([t]) => t);
const topThemes = themesRanked.slice(0, 3);
const summary = topThemes.length > 0
  ? `${channel}: ${messages.length} messages today. Top themes — ${topThemes.join(', ')}.`
  : `${channel}: ${messages.length} messages today. No dominant theme detected.`;

const ACTION_RULES = [
  { match: /timeout|latency|spike/i, owner: 'Engineering', task: 'Investigate API timeout / latency spike', priority: 'high' },
  { match: /design review|empty state/i, owner: 'Design', task: 'Run design review on flagged screens', priority: 'medium' },
  { match: /deadline|client review|slides/i, owner: 'Product', task: 'Lock client review deliverables before Friday', priority: 'high' },
  { match: /pricing|case study|prospect/i, owner: 'Marketing', task: 'Follow up on pricing / case study traction', priority: 'medium' },
  { match: /invoice|finance/i, owner: 'Finance', task: 'Confirm vendor invoice cycle', priority: 'low' },
  { match: /oncall/i, owner: 'On-call', task: 'Find Saturday oncall coverage', priority: 'medium' },
  { match: /security alert/i, owner: 'Security', task: 'Triage transitive dependency alert', priority: 'low' }
];

const actionItems = [];
const seen = new Set();
for (const m of messages) {
  for (const rule of ACTION_RULES) {
    if (rule.match.test(m.text || '')) {
      const key = `${rule.owner}|${rule.task}`;
      if (!seen.has(key)) {
        seen.add(key);
        actionItems.push({ owner: rule.owner, task: rule.task, priority: rule.priority });
      }
      break;
    }
  }
  if (actionItems.length >= maxActions) break;
}

const tokensIn = messages.reduce((sum, m) => sum + (m.text || '').length, 0);
const tokensOut = summary.length + risks.join(' ').length + JSON.stringify(actionItems).length;

return [{
  json: buildCallback(
    'success',
    {
      summary,
      data: {
        items_processed: messages.length,
        summary,
        risks,
        action_items: actionItems
      }
    },
    null,
    {
      input_count: messages.length,
      output_count: actionItems.length,
      error_count: 0,
      tokens_input: Math.ceil(tokensIn / 4),
      tokens_output: Math.ceil(tokensOut / 4),
      estimated_cost_usd: Number((messages.length * 0.0004).toFixed(4))
    }
  )
}];
